// When a rhotic vowel loses its r, the matching plain vowel wins; make those explicit errors.
const DROP_R = { 'ɑːɹ':'ɑː', 'ɔːɹ':'ɔː', 'oːɹ':'oʊ', 'ɛɹ':'ɛ', 'ɪɹ':'ɪ', 'ʊɹ':'ʊ', 'aɪɚ':'aɪ', 'ɚ':'ə', 'ɜː':'ʌ' };
for (const [k, v] of Object.entries(DROP_R)) { const r = RULES[k]; if (r && !r.ok.includes(v)) r.err.push(v); }

// Candidates (token ids) for each expected phone, cached.
const _cand = new Map();
export function candidates(tok) {
  if (_cand.has(tok)) return _cand.get(tok);
  const r = RULES[tok] || P([]);
  const ok = new Set([tok, ...r.ok]);
  const near = r.near.filter(t => !ok.has(t));
  const err = [...new Set([...EN_BASE, ...r.err])].filter(t => !ok.has(t) && !near.includes(t));
  const id = t => ID[t];
  const out = {
    ok: [...ok].map(id).filter(x => x != null),
    near: near.map(id).filter(x => x != null),
    err: err.map(id).filter(x => x != null),
  };
  _cand.set(tok, out);
  return out;
}

